class Solution:
    def wordPattern(self, pattern: str, s: str) -> bool:
        words = s.split()
        if len(pattern) != len(words):
            return False
        mapping = {}
        for ch, word in zip(pattern, words):
            if ch in mapping and mapping[ch] != word:
                return False
            mapping[ch] = word
        return True
